fn for_each(s: Str, item: Str, init: T, body: T) -> T {
    let i = 0
    let acc = init
    while i < str_len(s) {
        let c = get(s, i)?
        let acc = body
        if c == item {
            let count = acc + 1
            return count
        }
        i = i + 1
    }
    acc
}

